// TC-080 | req_ids: REQ-016 | level: api | type: api | model: shopcheck@25673b2
// Product state transition from active to deleted removes it from all reads
// Generated by the QA spec generator (rung 2) — deterministic assembly; do not hand-edit.

import { test, expect } from '../../../fixtures';

test('TC-080: Product state transition from active to deleted removes it from all reads', async ({ api, loginAs }) => {
  // reset_state is automatic (harness beforeEach)
  await api.get('/api/products');
  // Expected: Product initially present
  await loginAs('admin');  // admin-only endpoint (API contract roles)
  // runtime pick: active product not referenced by any open (pending/paid) order — delete-eligible (API contract)
  const orders: { id: number; user_id: number; status: string; items: { product_id: number; quantity: number; unit_price: number }[] }[] = await (await api.get('/api/orders')).json();
  const referencedIds = new Set(orders.filter((o) => o.status === 'pending' || o.status === 'paid').flatMap((o) => o.items.map((i) => i.product_id)));
  const products: { id: number; name: string; description: string; price: number; stock: number; is_active: boolean }[] = await (await api.get('/api/products')).json();
  const unreferencedProduct = products.find((p) => p.is_active && !referencedIds.has(p.id));
  if (!unreferencedProduct) throw new Error('seed has no active product unreferenced by open orders');
  const res = await api.delete(`/api/products/${unreferencedProduct.id}`);
  expect(res.status()).toBe(204);
  // Expected (full): Delete returns 204
  const res2 = await api.get(`/api/products/${unreferencedProduct.id}`);
  expect(res2.status()).toBe(404);
  // Expected (full): Returns 404
  await api.get('/api/products');
  // Expected: Product absent from catalog
});
